    narration: 'Switch to the animated construction to see the strip contributions accumulate across the surface. In the limit as the maximum strip thickness goes to zero, the Riemann sum becomes the integral from a to b.',
    state: { viewMode: 'Animated construction', stripCount: 20, stripIndex: 12 }
  }
];

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

function syncUi() {
  var n = state.stripCount;
  state.stripIndex = clamp(state.stripIndex, 1, n);
  var nIn = document.getElementById('stripCountInput');
  var kIn = document.getElementById('stripIndexInput');
  var vIn = document.getElementById('viewModeInput');
  if (nIn) nIn.value = n;
  if (kIn) {
    kIn.max = n;
    kIn.value = state.stripIndex;
  }
  if (document.getElementById('stripCountVal')) document.getElementById('stripCountVal').value = n;
  if (document.getElementById('stripIndexVal')) document.getElementById('stripIndexVal').value = state.stripIndex;
  if (vIn) vIn.checked = state.animated;
  if (document.getElementById('stepLabel')) document.getElementById('stepLabel').textContent = (state.step + 1) + '/' + demoSteps.length + ': ' + demoSteps[state.step].title;
  if (document.getElementById('demoNarration')) document.getElementById('demoNarration').textContent = demoSteps[state.step].narration;
}

function makeGradient() {
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#dff5ff');
    add.stop(1, '#86d3ee');
  });
  grad.from(0, 0).to(0, 1);
  return grad;
}

function txt(g, s, x, y, size, anchor) {
  return g.text(s).font({
    family: 'Times New Roman, serif',
    size: size || 28,
    style: 'italic',
    anchor: anchor || 'middle',
    leading: 1
  }).center(x, y).attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 4,
    'stroke-linejoin': 'round',
    fill: '#1f1f1f'
  });
}

function plainTxt(g, s, x, y, size, anchor) {
  return g.text(s).font({
    family: 'Arial, sans-serif',
    size: size || 15,
    anchor: anchor || 'middle',
    leading: 1.2
  }).center(x, y).attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 3,
    'stroke-linejoin': 'round',
    fill: '#222'
  });
}

function lineDash(g, x1, y1, x2, y2) {
  return g.line(x1, y1, x2, y2).stroke({ color: '#ff545c', width: 2.2, dasharray: '14 8', linecap: 'butt' });
}

function wavePath(x, y, w) {
  var d = 'M ' + x + ' ' + y;
  var amp = 3.5, step = 10;
  for (var i = 0; i <= w; i += step) {
    var mx = x + i + step / 2;
    var ex = x + i + step;
    d += ' Q ' + mx + ' ' + (y + amp * 2) + ' ' + ex + ' ' + y;
  }
  return d;
}

function arrowHead(g, x, y, dir, size) {
  size = size || 12;
  var pts;
  if (dir === 'down') pts = [[x - size * 0.55, y - size], [x + size * 0.55, y - size], [x, y]];
  if (dir === 'up') pts = [[x - size * 0.55, y + size], [x + size * 0.55, y + size], [x, y]];
  if (dir === 'left') pts = [[x + size, y - size * 0.55], [x + size, y + size * 0.55], [x, y]];
  if (dir === 'right') pts = [[x - size, y - size * 0.55], [x - size, y + size * 0.55], [x, y]];
  return g.polygon(pts.map(function (p) { return p.join(','); }).join(' ')).fill('#222').stroke('none');
}

function vDoubleArrow(g, x, y1, y2, color) {
  color = color || '#222';
  g.line(x, y1 + 10, x, y2 - 10).stroke({ color: color, width: 2 });
  arrowHead(g, x, y1, 'up', 11).fill(color);
  arrowHead(g, x, y2, 'down', 11).fill(color);
}

function hDoubleArrow(g, x1, x2, y, color) {
  color = color || '#222';
  g.line(x1 + 10, y, x2 - 10, y).stroke({ color: color, width: 2 });
  arrowHead(g, x1, y, 'left', 11).fill(color);
  arrowHead(g, x2, y, 'right', 11).fill(color);
}

function fluidPanel(g, p, grad) {
  g.rect(p.fw, p.fh).move(p.fx, p.y).fill(grad).stroke('none');
  g.path(wavePath(p.fx, p.y, p.fw)).fill('none').stroke({ color: '#222', width: 2.2 });
  g.line(p.axisX, p.y - 22, p.axisX, p.y + p.fh - 3).stroke({ color: '#222', width: 2.4 });
  arrowHead(g, p.axisX, p.y + p.fh - 2, 'down', 16);
}

function boundary(p, s) {
  s = clamp(s, 0, 1);
  var topX = p.blobTopX, bottomX = p.blobBottomX, bw = p.fw;
  var base = topX + (bottomX - topX) * s;
  var sin = Math.sin(Math.PI * s), sin2 = Math.sin(2 * Math.PI * s);
  return {
    y: p.aY + (p.bY - p.aY) * s,
    left: base - bw * (0.20 * sin + 0.08 * sin2),
    right: base + bw * (0.34 * sin - 0.08 * sin2 + 0.08 * sin * sin)
  };
}

function blobPath(p) {
  var ptsR = [], ptsL = [];
  for (var i = 0; i <= 70; i++) {
    var s = i / 70, b = boundary(p, s);
    ptsR.push([b.right, b.y]);
  }
  for (var j = 70; j >= 0; j--) {
    var s2 = j / 70, b2 = boundary(p, s2);
    ptsL.push([b2.left, b2.y]);
  }
  var pts = ptsR.concat(ptsL);
  var d = 'M ' + pts[0][0] + ' ' + pts[0][1];
  for (var k = 1; k < pts.length; k++) d += ' L ' + pts[k][0] + ' ' + pts[k][1];
  return d + ' Z';
}

function drawBlob(g, p, opacity) {
  var blob = g.path(blobPath(p)).fill({ color: '#ffda8d', opacity: opacity == null ? 1 : opacity })
    .stroke({ color: '#222', width: 2.4, linejoin: 'round' });
  blob.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Submerged vertical surface: its horizontal width depends on depth.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Submerged surface', 'The yellow region is a vertical plate or gate under fluid. At each depth, a horizontal chord gives the width w(x) used for a thin-strip area.'); });
  return blob;
}

function drawTick(g, p, y, label, size, off) {
  off = off == null ? 20 : off;
  g.line(p.axisX, y, p.axisX + 16, y).stroke({ color: '#222', width: 2 });
  txt(g, label, p.axisX - off, y, size || 30, 'middle');
}

function partitionStripPolygon(p, i0, i1) {
  var a = boundary(p, i0), b = boundary(p, i1);
  return [[a.left, a.y], [a.right, a.y], [b.right, b.y], [b.left, b.y]];
}

function polyAttr(pts) { return pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' '); }

function drawPanelA(root, grad) {
  var g = root.group();
  var p = { fx: 110, y: 25, fw: 480, fh: 330, axisX: 110, aY: 96, bY: 268, blobTopX: 388, blobBottomX: 280 };
  fluidPanel(g, p, grad);
  drawBlob(g, p);
  var s = 0.43, b = boundary(p, s), xY = b.y;
  lineDash(g, p.axisX, p.aY, p.blobTopX - 7, p.aY);
  lineDash(g, p.axisX, p.bY, p.blobBottomX + 4, p.bY);
  drawTick(g, p, p.aY, 'a', 32, 24);
  drawTick(g, p, xY, 'x', 32, 24);
  drawTick(g, p, p.bY, 'b', 32, 24);

  var chord = g.line(b.left, xY, b.right, xY).stroke({ color: '#20aeea', width: 2.4 });
  g.circle(14).center(b.left, xY).fill('#222');
  g.circle(14).center(b.right, xY).fill('#222');
  txt(g, 'w(x)', (b.left + b.right) / 2, xY - 28, 31);
  chord.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('w(x) is the horizontal width of the surface at depth x.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Width w(x)', 'The strip area is approximately its horizontal width times its small thickness. That is why w(x) appears in every Riemann-sum term.'); });

  var bx = p.fx + p.fw - 32;
  vDoubleArrow(g, bx, p.y + 5, xY, '#222');
  g.line(bx - 18, xY, bx + 18, xY).stroke({ color: '#222', width: 2 });
  txt(g, 'h(x)', bx, (p.y + xY) / 2 + 12, 32);

  txt(g, '(a)', W / 2, 395, 32);
}

function drawPanelB(root, grad) {
  var g = root.group();
  var n = state.stripCount, kSel = state.stripIndex;
  var p = { fx: 100, y: 455, fw: 490, fh: 430, axisX: 100, aY: 525, bY: 805, blobTopX: 380, blobBottomX: 250 };
  fluidPanel(g, p, grad);
  drawBlob(g, p);

  var hiPts = partitionStripPolygon(p, (kSel - 1) / n, kSel / n);
  var hi = g.polygon(polyAttr(hiPts)).fill({ color: '#b9e4ce', opacity: 0.65 }).stroke({ color: '#222', width: 1.2 });
  hi.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Selected strip k: pressure × approximate area.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('One Riemann-sum term', 'For the highlighted strip, choose a sample depth x*ₖ. Its force contribution is approximated by ρ h(x*ₖ) w(x*ₖ) Δxₖ.'); });

  for (var i = 0; i <= n; i++) {
    var s = i / n, b = boundary(p, s);
    lineDash(g, p.axisX, b.y, b.left, b.y);
    g.line(b.left, b.y, b.right, b.y).stroke({ color: '#20aeea', width: i === 0 || i === n ? 1.2 : 1.8, opacity: 0.9 });
  }

  function level(i) { return p.aY + (p.bY - p.aY) * i / n; }
  drawTick(g, p, level(0), 'a = x₀', 27, 55);
  drawTick(g, p, level(1), 'x₁', 25, 32);
  drawTick(g, p, level(Math.min(2, n)), 'x₂', 25, 32);
  drawTick(g, p, level(Math.min(3, n)), n >= 3 ? 'x₃' : '', 25, 32);
  txt(g, '⋮', p.axisX - 28, (p.aY + p.bY) / 2 + 15, 34);
  drawTick(g, p, level(n - 1), 'xₙ₋₁', 25, 50);
  drawTick(g, p, level(n), 'b = xₙ', 27, 55);

  var labelXs = p.fx + p.fw * 0.55;
  txt(g, 'A₁', labelXs, (level(0) + level(1)) / 2, 29);
  if (n >= 2) txt(g, 'A₂', labelXs, (level(1) + level(2)) / 2, 29);
  if (n >= 3) txt(g, 'A₃', labelXs, (level(2) + level(3)) / 2, 29);
  txt(g, '⋮', labelXs, (p.aY + p.bY) / 2 + 40, 32);
  txt(g, 'Aₙ', p.fx + p.fw * 0.32, (level(n - 1) + level(n)) / 2, 29);

  txt(g, '(b)', W / 2, 936, 32);
}

function drawPanelC(root, grad) {
  var g = root.group();
  var n = state.stripCount, k = state.stripIndex, sStar = (k - 0.5) / n;
  var p = { fx: 80, y: 1002, fw: 510, fh: 350, axisX: 80, aY: 1080, bY: 1285, blobTopX: 355, blobBottomX: 250 };
  fluidPanel(g, p, grad);
  drawBlob(g, p);

  drawTick(g, p, p.aY, 'a', 30, 24);
  drawTick(g, p, p.bY, 'b', 30, 24);

  var b = boundary(p, sStar);
  var yStar = b.y;
  var stripH = clamp((p.bY - p.aY) / n, 10, 36);
  var yTop = yStar - stripH / 2, yBot = yStar + stripH / 2;
  lineDash(g, p.axisX, yStar, b.right, yStar);

  var rect = g.rect(b.right - b.left, stripH).move(b.left, yTop)
    .fill({ color: '#b9e4ce', opacity: 0.9 })
    .stroke({ color: '#222', width: 1.6 });
  rect.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Approximate area: w(x*ₖ) Δxₖ.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Thin strip area', 'The curved strip is replaced by a rectangle. Its width is sampled at x*ₖ and its thickness is Δxₖ, so area ≈ w(x*ₖ)Δxₖ.'); });

  g.circle(13).center(p.axisX, yStar).fill('#222');
  g.circle(13).center(b.left, yStar).fill('#222');
  g.circle(13).center(b.right, yStar).fill('#222');
  txt(g, 'x*ₖ', p.axisX - 28, yStar, 27);
  txt(g, 'xₖ₋₁', p.axisX + 54, yTop - 6, 24);
  txt(g, 'xₖ', p.axisX + 47, yBot + 17, 24);
  g.line(p.axisX, yTop, p.axisX + 16, yTop).stroke({ color: '#222', width: 2 });
  g.line(p.axisX, yBot, p.axisX + 16, yBot).stroke({ color: '#222', width: 2 });

  hDoubleArrow(g, b.left, b.right, p.bY + 38, '#222');
  g.line(b.left, p.bY + 18, b.left, p.bY + 55).stroke({ color: '#222', width: 2 });
  g.line(b.right, p.bY + 18, b.right, p.bY + 55).stroke({ color: '#222', width: 2 });
  txt(g, 'w(x*ₖ)', (b.left + b.right) / 2, p.bY + 42, 29);

  var dxX = b.right + 36;
  vDoubleArrow(g, dxX, yTop, yBot, '#222');
  g.line(dxX - 18, yTop, dxX + 18, yTop).stroke({ color: '#222', width: 2 });
  g.line(dxX - 18, yBot, dxX + 18, yBot).stroke({ color: '#222', width: 2 });
  txt(g, 'Δxₖ', dxX + 25, yStar + 1, 29);

  var hx = p.fx + p.fw - 34;
  vDoubleArrow(g, hx, p.y + 10, yStar, '#222');
  g.line(hx - 20, yStar, hx + 20, yStar).stroke({ color: '#222', width: 2 });
  txt(g, 'h(x*ₖ)', hx - 2, (p.y + yStar) / 2 + 15, 28);

  txt(g, '(c)', W / 2, 1390, 32);
}

function drawFormula(root, y, animated) {
  var g = root.group();
  var f1 = txt(g, 'Fₙ ≈ Σ ρ h(x*ₖ) w(x*ₖ) Δxₖ', W / 2, y, 23);
  f1.font({ style: 'normal' });
  var f2 = txt(g, 'F = ∫ₐᵇ ρ h(x) w(x) dx', W / 2, y + 34, 23);
  f2.font({ style: 'normal' });
  if (animated) {
    var term = state.buildIndex <= 0 ? 'no strips added yet' : 'current total uses strips 1 through ' + state.buildIndex;
    plainTxt(g, term, W / 2, y + 66, 14);
  }
  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Riemann sum of pressure × strip area, then its limiting integral.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('From sum to integral', 'Each term multiplies pressure, ρh(x*ₖ), by approximate strip area, w(x*ₖ)Δxₖ. As the partition is refined, this Riemann sum tends to F = ∫ₐᵇ ρh(x)w(x) dx.'); });
}

function drawThreePanel() {
  draw.viewbox(0, 0, W, H3);
  draw.clear();
  var grad = makeGradient();
  var root = draw.group();
  drawPanelA(root, grad);
  drawPanelB(root, grad);
  drawPanelC(root, grad);
  drawFormula(root, 1335, false);
}

function drawAnimated() {
  draw.viewbox(0, 0, W, HA);
  draw.clear();
  var grad = makeGradient();
  var g = draw.group();
  var n = state.stripCount;
  var p = { fx: 92, y: 45, fw: 500, fh: 390, axisX: 92, aY: 122, bY: 355, blobTopX: 365, blobBottomX: 250 };
