  state.stripCount = st.stripCount;
  state.stripIndex = st.stripIndex;
  state.animated = st.viewMode === 'Animated construction';
  state.showBHighlight = !!st.showBHighlight;
  state.buildIndex = state.animated ? Math.min(state.stripIndex, state.stripCount) : 0;
  if (state.timer) {
    clearInterval(state.timer);
    state.timer = null;
  }
  render();
}

window.prevStep = function () { applyStep(state.step - 1); };
