function wavePath(x, y, w) {
  var d = 'M ' + x + ' ' + y;
  var amp = 5;
  var step = 14;
  for (var i = 0; i < w; i += step) {
    var ex = Math.min(x + i + step, x + w);
    var mx = (x + i + ex) / 2;
    d += ' Q ' + mx + ' ' + (y + amp * 1.85) + ' ' + ex + ' ' + y;
  }
  return d;
}

function arrowHead(g, x, y, dir, size, color) {
  size = size || 13;
  color = color || '#222';
  var pts;
  if (dir === 'down') pts = [[x - size * 0.55, y - size], [x + size * 0.55, y - size], [x, y]];
  if (dir === 'up') pts = [[x - size * 0.55, y + size], [x + size * 0.55, y + size], [x, y]];
  if (dir === 'left') pts = [[x + size, y - size * 0.55], [x + size, y + size * 0.55], [x, y]];
  if (dir === 'right') pts = [[x - size, y - size * 0.55], [x - size, y + size * 0.55], [x, y]];
  return g.polygon(pts.map(function (p) { return p.join(','); }).join(' ')).fill(color).stroke('none');
}

function vDoubleArrow(g, x, y1, y2, color) {
  color = color || '#222';
  g.line(x, y1 + 12, x, y2 - 12).stroke({ color: color, width: 2.4 });
  arrowHead(g, x, y1, 'up', 13, color);
  arrowHead(g, x, y2, 'down', 13, color);
}

function hDoubleArrow(g, x1, x2, y, color) {
  color = color || '#222';
  g.line(x1 + 13, y, x2 - 13, y).stroke({ color: color, width: 2.4 });
  arrowHead(g, x1, y, 'left', 13, color);
  arrowHead(g, x2, y, 'right', 13, color);
}

function fluidPanel(g, p, grad) {
  g.rect(p.fw, p.fh).move(p.fx, p.y).fill(grad).stroke('none');
  g.path(wavePath(p.fx, p.y, p.fw)).fill('none').stroke({ color: '#222', width: 2.6, linecap: 'round' });
  g.line(p.axisX, p.y - 36, p.axisX, p.y + p.fh - 4).stroke({ color: '#222', width: 3.0 });
  arrowHead(g, p.axisX, p.y + p.fh - 2, 'down', 18, '#222');
}

function gauss(s, m, q) {
  return Math.exp(-Math.pow((s - m) / q, 2));
}

function boundary(p, s) {
  s = clamp(s, 0, 1);
  var y = p.aY + (p.bY - p.aY) * s;
  var top = p.topX, bottom = p.bottomX, fw = p.fw;
  var sin = Math.sin(Math.PI * s);
  var c = top + (bottom - top) * s + fw * (0.070 * sin - 0.040 * Math.sin(2 * Math.PI * s));
  var leftReach = fw * (0.010 + 0.260 * Math.pow(sin, 0.78) + 0.050 * gauss(s, 0.80, 0.18) - 0.032 * gauss(s, 0.18, 0.18));
  var rightReach = fw * (0.015 + 0.315 * Math.pow(sin, 0.58) + 0.135 * gauss(s, 0.42, 0.30) + 0.080 * gauss(s, 0.66, 0.19));
  var pinch = 1 - 0.16 * gauss(s, 0.74, 0.16);
  return {
    y: y,
    left: c - leftReach,
    right: c + rightReach * pinch
  };
}

function smoothClosedPath(pts) {
  var d = 'M ' + pts[0][0] + ' ' + pts[0][1];
  for (var i = 1; i < pts.length; i++) {
    var mx = (pts[i][0] + pts[(i + 1) % pts.length][0]) / 2;
    var my = (pts[i][1] + pts[(i + 1) % pts.length][1]) / 2;
    d += ' Q ' + pts[i][0] + ' ' + pts[i][1] + ' ' + mx + ' ' + my;
  }
  var m0x = (pts[0][0] + pts[1][0]) / 2;
  var m0y = (pts[0][1] + pts[1][1]) / 2;
  d += ' Q ' + pts[0][0] + ' ' + pts[0][1] + ' ' + m0x + ' ' + m0y + ' Z';
  return d;
}

function blobPath(p) {
  var pts = [];
  for (var i = 0; i <= 72; i++) {
    var br = boundary(p, i / 72);
    pts.push([br.right, br.y]);
  }
  for (var j = 72; j >= 0; j--) {
    var bl = boundary(p, j / 72);
    pts.push([bl.left, bl.y]);
  }
  return smoothClosedPath(pts);
}

function drawBlob(g, p, opacity) {
  var blob = g.path(blobPath(p)).fill({ color: '#ffdc91', opacity: opacity == null ? 1 : opacity })
