}

userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600">Fluid force by horizontal strips</span><label>Number of strips n: <output id="stripCountVal">8</output><input id="stripCountInput" type="range" min="3" max="30" step="1" value="8" oninput="document.getElementById('stripCountVal').value=this.value;update_stripCount(+this.value)"></label><label>Selected strip k: <output id="stripIndexVal">4</output><input id="stripIndexInput" type="range" min="1" max="30" step="1" value="4" oninput="document.getElementById('stripIndexVal').value=this.value;update_stripIndex(+this.value)"></label><label><input id="viewModeInput" type="checkbox" onchange="toggle_viewMode(this.checked)"> Animated construction</label><button onclick="trigger_buildSum()">Animate accumulated pressure sum</button><button onclick="pauseBuildSum()">Pause</button><button onclick="resetBuildSum()">Reset sum</button><span id="demoNarration" style="display:block;margin-top:6px;font-size:10px;max-width:260px">At a depth x below the fluid surface, the pressure depends on depth through h(x), while the surface contributes a horizontal width w(x). This gives the ingredients for the force on a very thin strip.</span><span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
document.body.style.setProperty('--figure-canvas-padding', '2px');

var W = 980;
var H3 = 1510;
var HA = 820;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H3);
draw.node.setAttribute('preserveAspectRatio', 'xMidYMid meet');

var state = {
  stripCount: 8,
  stripIndex: 4,
  animated: false,
  buildIndex: 0,
  timer: null,
  step: 0,
  showBHighlight: false
};

var demoSteps = [
  {
    title: 'Start with one depth slice',
    narration: 'At a depth x below the fluid surface, the pressure depends on depth through h(x), while the surface contributes a horizontal width w(x). This gives the ingredients for the force on a very thin strip.',
    state: { viewMode: 'Three-panel derivation', stripCount: 8, stripIndex: 4, showBHighlight: false }
  },
  {
    title: 'Partition the surface',
    narration: 'The interval from a to b is divided into n horizontal strips. Moving the selected k highlights one strip and shows the corresponding sample depth, width, and thickness in the close-up.',
    state: { viewMode: 'Three-panel derivation', stripCount: 8, stripIndex: 6, showBHighlight: true }
  },
  {
    title: 'Refine the approximation',
    narration: 'Increasing n makes the strips thinner, so each curved strip is better approximated by a rectangle of area w(xₖ*) Δxₖ. The displayed sum becomes a better approximation to the true fluid force.',
    state: { viewMode: 'Three-panel derivation', stripCount: 20, stripIndex: 12, showBHighlight: true }
  },
  {
    title: 'Watch the sum become an integral',
    narration: 'Switch to the animated construction to see the strip contributions accumulate across the surface. In the limit as the maximum strip thickness goes to zero, the Riemann sum becomes the integral from a to b.',
    state: { viewMode: 'Animated construction', stripCount: 20, stripIndex: 12, showBHighlight: true }
  }
];

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

function syncUi() {
  state.stripIndex = clamp(state.stripIndex, 1, state.stripCount);
  var nIn = document.getElementById('stripCountInput');
  var kIn = document.getElementById('stripIndexInput');
  var vIn = document.getElementById('viewModeInput');
  if (nIn) nIn.value = state.stripCount;
  if (kIn) {
    kIn.max = state.stripCount;
    kIn.value = state.stripIndex;
  }
  if (document.getElementById('stripCountVal')) document.getElementById('stripCountVal').value = state.stripCount;
  if (document.getElementById('stripIndexVal')) document.getElementById('stripIndexVal').value = state.stripIndex;
  if (vIn) vIn.checked = state.animated;
  if (document.getElementById('stepLabel')) document.getElementById('stepLabel').textContent = (state.step + 1) + '/' + demoSteps.length + ': ' + demoSteps[state.step].title;
  if (document.getElementById('demoNarration')) document.getElementById('demoNarration').textContent = demoSteps[state.step].narration;
}

function makeGradient() {
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#dff5ff');
    add.stop(1, '#86d3ee');
  });
  grad.from(0, 0).to(0, 1);
  return grad;
}

function txt(g, s, x, y, size, anchor) {
  return g.text(s).font({
    family: 'Times New Roman, Times, serif',
    size: size || 34,
    style: 'italic',
    anchor: anchor || 'middle',
    leading: 1
  }).center(x, y).attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 5,
    'stroke-linejoin': 'round',
    fill: '#1f1f1f'
  });
}

function plainTxt(g, s, x, y, size, anchor) {
  return g.text(s).font({
    family: 'Arial, sans-serif',
    size: size || 17,
    anchor: anchor || 'middle',
    leading: 1.2
  }).center(x, y).attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 3,
    'stroke-linejoin': 'round',
    fill: '#222'
  });
}

function lineDash(g, x1, y1, x2, y2) {
  return g.line(x1, y1, x2, y2).stroke({ color: '#ff545c', width: 2.4, dasharray: '18 11', linecap: 'butt' });
}

function wavePath(x, y, w) {
  var d = 'M ' + x + ' ' + y;
  var amp = 5;
  var step = 17;
  for (var i = 0; i < w; i += step) {
    var ex = Math.min(x + i + step, x + w);
    var mx = (x + i + ex) / 2;
    d += ' Q ' + mx + ' ' + (y + amp * 1.75) + ' ' + ex + ' ' + y;
  }
  return d;
}

function arrowHead(g, x, y, dir, size, color) {
  size = size || 13;
  color = color || '#222';
  var pts;
  if (dir === 'down') pts = [[x - size * 0.55, y - size], [x + size * 0.55, y - size], [x, y]];
  if (dir === 'up') pts = [[x - size * 0.55, y + size], [x + size * 0.55, y + size], [x, y]];
  if (dir === 'left') pts = [[x + size, y - size * 0.55], [x + size, y + size * 0.55], [x, y]];
  if (dir === 'right') pts = [[x - size, y - size * 0.55], [x - size, y + size * 0.55], [x, y]];
  return g.polygon(pts.map(function (p) { return p.join(','); }).join(' ')).fill(color).stroke('none');
}

function vDoubleArrow(g, x, y1, y2, color) {
  color = color || '#222';
  g.line(x, y1 + 14, x, y2 - 14).stroke({ color: color, width: 2.6 });
  arrowHead(g, x, y1, 'up', 14, color);
  arrowHead(g, x, y2, 'down', 14, color);
}

function hDoubleArrow(g, x1, x2, y, color) {
  color = color || '#222';
  g.line(x1 + 15, y, x2 - 15, y).stroke({ color: color, width: 2.6 });
  arrowHead(g, x1, y, 'left', 14, color);
  arrowHead(g, x2, y, 'right', 14, color);
}

function fluidPanel(g, p, grad) {
  g.rect(p.fw, p.fh).move(p.fx, p.y).fill(grad).stroke('none');
  g.path(wavePath(p.fx, p.y, p.fw)).fill('none').stroke({ color: '#222', width: 2.8, linecap: 'round' });
  g.line(p.axisX, p.y - 34, p.axisX, p.y + p.fh - 7).stroke({ color: '#222', width: 3.4 });
  arrowHead(g, p.axisX, p.y + p.fh - 2, 'down', 18, '#222');
}

function boundary(p, s) {
  s = clamp(s, 0, 1);
  var y = p.aY + (p.bY - p.aY) * s;
  var sin = Math.sin(Math.PI * s);
  var c = p.topX + (p.bottomX - p.topX) * s + p.fw * (0.040 * sin - 0.035 * Math.sin(2 * Math.PI * s));
  var leftReach = p.fw * (0.020 + 0.245 * Math.pow(sin, 0.72) + 0.045 * Math.exp(-Math.pow((s - 0.82) / 0.18, 2)) - 0.025 * Math.exp(-Math.pow((s - 0.16) / 0.16, 2)));
  var rightReach = p.fw * (0.025 + 0.315 * Math.pow(sin, 0.66) + 0.080 * Math.exp(-Math.pow((s - 0.37) / 0.24, 2)) + 0.035 * Math.exp(-Math.pow((s - 0.68) / 0.22, 2)));
  var lowerRound = 1 - 0.055 * Math.exp(-Math.pow((s - 0.78) / 0.16, 2));
  return { y: y, left: c - leftReach, right: c + rightReach * lowerRound };
}

function blobPath(p) {
  var pts = [];
  for (var i = 0; i <= 96; i++) {
    var br = boundary(p, i / 96);
    pts.push([br.right, br.y]);
  }
  for (var j = 96; j >= 0; j--) {
    var bl = boundary(p, j / 96);
    pts.push([bl.left, bl.y]);
  }
  var d = 'M ' + pts[0][0] + ' ' + pts[0][1];
  for (var k = 1; k < pts.length; k++) {
    var p0 = pts[k - 1], p1 = pts[k];
    d += ' Q ' + p0[0] + ' ' + p0[1] + ' ' + ((p0[0] + p1[0]) / 2) + ' ' + ((p0[1] + p1[1]) / 2);
  }
  d += ' Q ' + pts[pts.length - 1][0] + ' ' + pts[pts.length - 1][1] + ' ' + pts[0][0] + ' ' + pts[0][1] + ' Z';
  return d;
}

function drawBlob(g, p, opacity) {
  var blob = g.path(blobPath(p)).fill({ color: '#ffdc91', opacity: opacity == null ? 1 : opacity })
    .stroke({ color: '#222', width: 2.8, linejoin: 'round', linecap: 'round' });
  blob.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Submerged vertical surface: its horizontal width changes with depth.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Submerged surface', 'The yellow region is a vertical surface under fluid. A horizontal slice through the region has width w(x), which determines the strip area.'); });
  return blob;
}

function drawTick(g, p, y, label, size, off) {
  off = off == null ? 28 : off;
  g.line(p.axisX, y, p.axisX + 23, y).stroke({ color: '#222', width: 2.8 });
  if (label) txt(g, label, p.axisX - off, y, size || 38, 'middle');
}

function partitionStripPolygon(p, s0, s1) {
  var a = boundary(p, s0), b = boundary(p, s1);
  return [[a.left, a.y], [a.right, a.y], [b.right, b.y], [b.left, b.y]];
}

function polyAttr(pts) { return pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' '); }

function drawPanelLabel(g, label, y) {
  var t = txt(g, label, W / 2, y, 44);
  t.font({ style: 'italic' });
}

function drawPanelA(root, grad) {
  var g = root.group();
  var p = { fx: 170, y: 28, fw: 760, fh: 360, axisX: 170, aY: 112, bY: 298, topX: 600, bottomX: 505 };
  fluidPanel(g, p, grad);
  drawBlob(g, p);

  var s = 0.43, b = boundary(p, s), xY = b.y;
  lineDash(g, p.axisX, p.aY, p.topX - 10, p.aY);
  lineDash(g, p.axisX, p.bY, p.bottomX + 5, p.bY);
  drawTick(g, p, p.aY, 'a', 46, 38);
  drawTick(g, p, xY, 'x', 46, 38);
  drawTick(g, p, p.bY, 'b', 46, 38);

  var chord = g.line(b.left, xY, b.right, xY).stroke({ color: '#18aee9', width: 3.2 });
  g.circle(17).center(b.left, xY).fill('#222');
  g.circle(17).center(b.right, xY).fill('#222');
  txt(g, 'w(x)', (b.left + b.right) / 2, xY - 35, 42);
  chord.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('w(x) is the horizontal width of the surface at depth x.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Width w(x)', 'A thin horizontal strip has approximate area w(x) times its thickness. This is the geometric part of each fluid-force term.'); });

  var hx = p.fx + p.fw - 48;
  vDoubleArrow(g, hx, p.y + 9, xY, '#222');
  g.line(hx - 31, xY, hx + 31, xY).stroke({ color: '#222', width: 2.6 });
  txt(g, 'h(x)', hx + 2, (p.y + xY) / 2 + 11, 42);

  drawPanelLabel(g, '(a)', 452);
}

function drawPanelB(root, grad) {
  var g = root.group();
  var n = state.stripCount, kSel = state.stripIndex;
  var p = { fx: 150, y: 520, fw: 780, fh: 390, axisX: 150, aY: 615, bY: 825, topX: 600, bottomX: 505 };
  fluidPanel(g, p, grad);
  drawBlob(g, p);

  if (state.showBHighlight) {
    var hiPts = partitionStripPolygon(p, (kSel - 1) / n, kSel / n);
    g.polygon(polyAttr(hiPts)).fill({ color: '#b9e4ce', opacity: 0.58 }).stroke({ color: '#222', width: 1.2 })
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Selected strip k: one term of the Riemann sum.', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('One Riemann-sum term', 'For this strip, pressure is evaluated at a sample depth xₖ*. The strip contribution is approximately ρ h(xₖ*) w(xₖ*) Δxₖ.'); });
  }

  for (var i = 0; i <= n; i++) {
    var s = i / n, br = boundary(p, s);
    lineDash(g, p.axisX, br.y, br.left, br.y);
    g.line(br.left, br.y, br.right, br.y).stroke({ color: '#18aee9', width: i === 0 || i === n ? 1.6 : 2.1, opacity: 0.95 });
  }

  function level(i) { return p.aY + (p.bY - p.aY) * i / n; }
  drawTick(g, p, level(0), 'a = x₀', 38, 86);
  drawTick(g, p, level(1), 'x₁', 35, 48);
  drawTick(g, p, level(Math.min(2, n)), 'x₂', 35, 48);
  drawTick(g, p, level(Math.min(3, n)), n >= 3 ? 'x₃' : '', 35, 48);
  txt(g, '⋮', p.axisX - 52, (p.aY + p.bY) / 2 + 16, 46);
  drawTick(g, p, level(n - 1), 'xₙ₋₁', 35, 72);
  drawTick(g, p, level(n), 'b = xₙ', 38, 86);

  var lx = p.fx + p.fw * 0.56;
  txt(g, 'A₁', lx, (level(0) + level(1)) / 2 + 2, 43);
  if (n >= 2) txt(g, 'A₂', lx, (level(1) + level(2)) / 2 + 2, 43);
  if (n >= 3) txt(g, 'A₃', lx, (level(2) + level(3)) / 2 + 2, 43);
  txt(g, '⋮', lx, (p.aY + p.bY) / 2 + 27, 50);
  txt(g, 'Aₙ', p.fx + p.fw * 0.32, (level(n - 1) + level(n)) / 2 - 1, 43);

  drawPanelLabel(g, '(b)', 980);
}

function drawPanelC(root, grad) {
  var g = root.group();
  var n = state.stripCount, k = state.stripIndex, sStar = (k - 0.5) / n;
  var p = { fx: 82, y: 1050, fw: 848, fh: 375, axisX: 82, aY: 1138, bY: 1333, topX: 560, bottomX: 465 };
  fluidPanel(g, p, grad);
  drawBlob(g, p);

  drawTick(g, p, p.aY, 'a', 43, 38);
  drawTick(g, p, p.bY, 'b', 43, 38);

  var br = boundary(p, sStar);
  var yStar = br.y;
  var stripH = clamp((p.bY - p.aY) / n, 16, 38);
  var yTop = yStar - stripH / 2, yBot = yStar + stripH / 2;

  lineDash(g, p.axisX, yStar, br.right + 7, yStar);

  var rect = g.rect(br.right - br.left, stripH).move(br.left, yTop)
    .fill({ color: '#b9e4ce', opacity: 0.93 })
    .stroke({ color: '#222', width: 2.3 });
  rect.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Approximate area of selected strip: w(xₖ*) Δxₖ.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Thin strip area', 'The actual curved strip is approximated by a rectangle. Its width is sampled at xₖ* and its thickness is Δxₖ.'); });

  g.circle(17).center(p.axisX, yStar).fill('#222');
  g.circle(17).center(br.left, yStar).fill('#222');
  g.circle(17).center(br.right, yStar).fill('#222');

  txt(g, 'xₖ*', p.axisX - 45, yStar, 39);
  txt(g, 'xₖ₋₁', p.axisX + 72, yTop - 18, 36);
  txt(g, 'xₖ', p.axisX + 66, yBot + 22, 36);
  g.line(p.axisX, yTop, p.axisX + 27, yTop).stroke({ color: '#222', width: 2.5 });
  g.line(p.axisX, yBot, p.axisX + 27, yBot).stroke({ color: '#222', width: 2.5 });

  hDoubleArrow(g, br.left, br.right, p.bY + 46, '#222');
  g.line(br.left, p.bY + 18, br.left, p.bY + 64).stroke({ color: '#222', width: 2.5 });
  g.line(br.right, p.bY + 18, br.right, p.bY + 64).stroke({ color: '#222', width: 2.5 });
  txt(g, 'w(xₖ*)', (br.left + br.right) / 2, p.bY + 46, 42);

  var dxX = br.right + 57;
  vDoubleArrow(g, dxX, yTop, yBot, '#222');
  g.line(dxX - 32, yTop, dxX + 32, yTop).stroke({ color: '#222', width: 2.5 });
  g.line(dxX - 32, yBot, dxX + 32, yBot).stroke({ color: '#222', width: 2.5 });
  txt(g, 'Δxₖ', dxX + 42, yStar + 3, 41);

  var hx = p.fx + p.fw - 58;
  vDoubleArrow(g, hx, p.y + 10, yStar, '#222');
  g.line(hx - 34, yStar, hx + 34, yStar).stroke({ color: '#222', width: 2.5 });
  txt(g, 'h(xₖ*)', hx + 2, (p.y + yStar) / 2 + 11, 39);

  drawPanelLabel(g, '(c)', 1480);
}

function drawFormula(root, y) {
  var g = root.group();
  var f1 = txt(g, 'Fₙ ≈ Σ ρ h(xₖ*) w(xₖ*) Δxₖ', W / 2, y, 32);
  f1.font({ style: 'normal' });
  var f2 = txt(g, 'F = ∫ₐᵇ ρ h(x) w(x) dx', W / 2, y + 48, 32);
  f2.font({ style: 'normal' });
  var term = state.buildIndex <= 0 ? 'no strips added yet' : 'current total uses strips 1 through ' + state.buildIndex;
  plainTxt(g, term, W / 2, y + 90, 18);
  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Riemann sum of pressure times strip area, approaching the limiting integral.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('From sum to integral', 'Each strip contributes pressure ρh(xₖ*) times approximate area w(xₖ*)Δxₖ. Refining the partition turns the sum into the integral F = ∫ₐᵇ ρh(x)w(x) dx.'); });
}

function drawThreePanel() {
  draw.viewbox(0, 0, W, H3);
  draw.node.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  draw.clear();
  var grad = makeGradient();
  var root = draw.group();
  drawPanelA(root, grad);
  drawPanelB(root, grad);
  drawPanelC(root, grad);
}

function drawAnimated() {
  draw.viewbox(0, 0, W, HA);
  draw.node.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  draw.clear();
  var grad = makeGradient();
  var g = draw.group();
  var n = state.stripCount;
  var p = { fx: 118, y: 38, fw: 810, fh: 435, axisX: 118, aY: 126, bY: 392, topX: 585, bottomX: 485 };
  fluidPanel(g, p, grad);
  drawBlob(g, p);
  drawTick(g, p, p.aY, 'a', 39, 34);
  drawTick(g, p, p.bY, 'b', 39, 34);

  for (var i = 1; i <= Math.min(state.buildIndex, n); i++) {
    var s0 = (i - 1) / n, s1 = i / n, mid = (i - 0.5) / n;
    g.polygon(polyAttr(partitionStripPolygon(p, s0, s1)))
      .fill({ color: '#9fd8be', opacity: 0.22 + 0.34 * mid })
      .stroke('none')
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Already-added strip contribution in the running sum.', e); })
      .on('mouseleave', hideTooltip);
  }

  for (var j = 0; j <= n; j++) {
    var b = boundary(p, j / n);
    lineDash(g, p.axisX, b.y, b.left, b.y);
    g.line(b.left, b.y, b.right, b.y).stroke({ color: '#18aee9', width: 2.0, opacity: 0.96 });
  }

  var current = clamp(state.buildIndex || state.stripIndex, 1, n);
  var sTop = (current - 1) / n, sBot = current / n, sMid = (current - 0.5) / n;
  var hi = g.polygon(polyAttr(partitionStripPolygon(p, sTop, sBot)))
    .fill({ color: '#b9e4ce', opacity: 0.82 })
    .stroke({ color: '#222', width: 1.9 });
  var bm = boundary(p, sMid);
  g.circle(14).center(p.axisX, bm.y).fill('#222');
  g.circle(14).center(bm.left, bm.y).fill('#222');
  g.circle(14).center(bm.right, bm.y).fill('#222');
  lineDash(g, p.axisX, bm.y, bm.right + 7, bm.y);
  txt(g, 'xₖ*', p.axisX - 38, bm.y, 34);
  txt(g, 'w(xₖ*)', (bm.left + bm.right) / 2, bm.y - 30, 34);
  vDoubleArrow(g, p.fx + p.fw - 47, p.y + 10, bm.y, '#222');
  txt(g, 'h(xₖ*)', p.fx + p.fw - 47, (p.y + bm.y) / 2 + 10, 34);

  hi.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('The highlighted term being added: ρ h(xₖ*) w(xₖ*) Δxₖ.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Accumulating force', 'The animation adds strip terms one at a time. The highlighted strip represents the current pressure-at-depth times strip-area contribution.'); });

  var status = state.buildIndex >= n ? 'all n strips added' : 'adding strip k = ' + current + ' of n = ' + n;
  plainTxt(g, status, W / 2, 522, 20);
  drawFormula(g, 585);
}

function render() {
  syncUi();
  if (state.animated) drawAnimated(); else drawThreePanel();
}

window.update_stripCount = function (v) {
  state.stripCount = clamp(Math.round(v), 3, 30);
  state.stripIndex = clamp(state.stripIndex, 1, state.stripCount);
  state.buildIndex = Math.min(state.buildIndex, state.stripCount);
  state.showBHighlight = true;
  render();
};

window.update_stripIndex = function (v) {
  state.stripIndex = clamp(Math.round(v), 1, state.stripCount);
  state.showBHighlight = true;
  if (!state.timer && state.animated) state.buildIndex = state.stripIndex;
  render();
};

window.toggle_viewMode = function (on) {
  state.animated = !!on;
  state.showBHighlight = true;
  if (state.animated && state.buildIndex === 0) state.buildIndex = state.stripIndex;
  render();
};

window.trigger_buildSum = function () {
  if (state.timer) clearInterval(state.timer);
  state.animated = true;
  state.showBHighlight = true;
  state.buildIndex = 0;
  syncUi();
  state.timer = setInterval(function () {
    state.buildIndex += 1;
